  assert.strictEqual(computeTotal({ subtotal: 10000, taxPercent: 10, shipping: 500 }), 11500);
});

test('tax and shipping with zero coupon', () => {
  assert.strictEqual(computeTotal({ subtotal: 5000, couponPercent: 0, taxPercent: 8, shipping: 0 }), 5400);
});
